import subprocess,json
script="""import os,json,urllib.request,concurrent.futures,time
headers={'Authorization':'Bearer '+os.environ['AI_CORE_API_KEY'],'Content-Type':'application/json'}
base='http://127.0.0.1:'
def call(model,label,limit=6):
 port={'coder':18184,'granite':18181}[model]
 with urllib.request.urlopen(urllib.request.Request(base+str(port)+'/v1/models',headers=headers),timeout=6) as r:mid=json.load(r)['data'][0]['id']
 body={'model':mid,'stream':False,'messages':[{'role':'system','content':'Answer using a single short English word. No reasoning.'},{'role':'user','content':'Say OK.'}],'max_tokens':limit,'temperature':0}
 h={**headers,'X-AI-Core-Client':label,'X-AI-Core-Wait-Ms':'30000'}
 start=time.monotonic()
 req=urllib.request.Request(base+str(port)+'/v1/chat/completions',data=json.dumps(body).encode(),headers=h)
 with urllib.request.urlopen(req,timeout=180) as r:
  data=json.load(r)
  return {'model':model,'client':label,'http':r.status,'choices':len(data.get('choices',[])),'elapsed':round(time.monotonic()-start,2),'content_size':len(str(data.get('choices',[{}])[0].get('message',{}).get('content') or ''))}
out={'warmup':[]}
for model in ('granite','coder'):
 try:out['warmup'].append(call(model,'warmup-'+model))
 except Exception as e:out['warmup'].append({'model':model,'error':type(e).__name__+': '+str(e)[:150]})
if all(x.get('http')==200 for x in out['warmup']):
 with concurrent.futures.ThreadPoolExecutor(max_workers=2) as executor:
  fs=[executor.submit(call,m,'independent-'+m) for m in ('granite','coder')]
  out['parallel']=[]
  for f in fs:
   try:out['parallel'].append(f.result(timeout=180))
   except Exception as e:out['parallel'].append({'error':type(e).__name__+': '+str(e)[:150]})
print(json.dumps(out))
"""
