r=subprocess.run(['gh','api','-X','POST','repos/G-ACE-inc/server-core/issues/10/comments','--input','-','--jq','.html_url'],input=json.dumps({'body':'AI_CORE_TWO_INDEPENDENT_CALLERS_REAL_E2E\n'+json.dumps(out,ensure_ascii=False,indent=2)}),capture_output=True,text=True,timeout=25)
print('AI_CORE_E2E='+('RECORD '+r.stdout.strip() if r.returncode==0 else 'RECORD_FAILED'))
s=out.get('result',{})
ok=p.returncode==0 and all(x.get('http')==200 and x.get('choices',0)>0 for x in s.get('warmup',[])+s.get('parallel',[])) and len(s.get('parallel',[]))==2
print('AI_CORE_INDEPENDENT_CALLERS='+('PASS' if ok else 'FAIL'))
raise SystemExit(0 if ok and r.returncode==0 else 1)
